if (kind !== 'image' && kind !== 'video') throw new Error('Muse 网页插件目前只支持图片(image)和视频(video)');
const raw = String(args.prompt || '').trim();
if (!raw) throw new Error('缺少提示词 prompt');
let prompt = raw;
if (kind === 'image') {
  if (!/(?:image|photo|draw|paint|picture|画|图|照片|海报)/i.test(prompt)) prompt = 'Generate an image: ' + prompt;
  if (args.size) prompt += ` (aspect/size: ${args.size})`;
} else {
  const dur = args.duration ? `${args.duration}-second ` : '';
  if (!/(?:video|clip|animation|视频|短片|动画)/i.test(prompt)) prompt = `Generate a short ${dur}video: ` + prompt;
  else if (args.duration) prompt += ` (${args.duration} seconds)`;
  if (args.size) prompt += ` (aspect/size: ${args.size})`;
}
return tools.openTab('https://muse.ai/thread/new', async tabId => {
  let ready = false;
  for (let i = 0; i < 20; i++) {
    ready = await tools.evalTab(tabId, `(() => { const ta = document.querySelector('textarea'); return !!(ta && Object.keys(ta).some(k => k.startsWith('__reactProps'))); })()`).catch(() => false);
    if (ready) break;
    await tools.sleep(500);
  }
  if (!ready) throw new Error('Muse 页面未就绪，请先在浏览器打开 https://muse.ai 确认登录状态');
  const sent = await tools.evalTab(tabId, `(async () => {
    const ta = document.querySelector('textarea');
    if (!ta) return { ok: false, err: '找不到输入框' };
    ta.focus();
    Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set.call(ta, ${JSON.stringify(prompt)});
    ta.dispatchEvent(new Event('input', { bubbles: true }));
    ta.dispatchEvent(new Event('change', { bubbles: true }));
    await new Promise(r => setTimeout(r, 350));
    let p = ta.parentElement;
    for (let i = 0; i < 4 && p && p.parentElement !== document.body; i++) p = p.parentElement;
    const btn = [...p.querySelectorAll('button,[role="button"]')].find(b => !b.disabled
      && b.getAttribute('aria-disabled') !== 'true'
      && (/^(?:send(?:\\s+message)?|发送(?:消息)?|發送(?:訊息)?|送出)$/i.test((b.getAttribute('aria-label') || b.innerText || '').trim())
        || /send-button/i.test(b.getAttribute('data-testid') || '')));
    if (!btn) return { ok: false, err: '找不到发送按钮' };
    btn.click();
    return { ok: true };
  })()`);
  if (!sent?.ok) throw new Error('Muse 提交失败: ' + (sent?.err || '未知错误'));
  const maxWait = kind === 'video' ? 180000 : 90000;
  const deadline = Date.now() + maxWait;
  const wantTid = kind === 'video' ? 'hatch-chat-attachment-presentation-video' : 'hatch-chat-attachment-presentation-image';
  let started = false, lastText = '', hasTarget = false;
  while (Date.now() < deadline) {
    await tools.sleep(2000);
    const st = await tools.evalTab(tabId, `(() => {
      const atts = [...document.querySelectorAll('[data-testid^="hatch-chat-attachment-presentation-"]')].map(a => a.getAttribute('data-testid'));
      const stop = !!(document.querySelector('[data-testid="hatch-composer-stop-button"]') || document.querySelector('button[aria-label*="Stop" i]') || document.querySelector('button[aria-label*="停止"]'));
      const bubbles = [...document.querySelectorAll('div[class*="hatch-agent-bubble-bg"]')].map(b => (b.innerText || '').trim()).filter(Boolean);
      return { atts, stop, text: bubbles[bubbles.length - 1] || (document.body.innerText || '').trim().slice(-300) };
    })()`);
    if (st.stop || st.atts.length) started = true;
    lastText = st.text || lastText;
    hasTarget = st.atts.includes(wantTid);
    if (hasTarget && !st.stop) break;
    if (started && !st.stop && st.atts.length === 0 && Date.now() > deadline - maxWait + 12000) break;
  }
  if (!hasTarget) throw new Error('Muse 未产出目标媒体' + (lastText ? ': ' + lastText.slice(0, 180) : '（超时）'));
  const best = await tools.evalTab(tabId, `(async () => {
    const att = document.querySelector('[data-testid="${wantTid}"]');
    const btn = att && att.querySelector('button');
    if (btn) { btn.click(); await new Promise(r => setTimeout(r, 1400)); }
    const nodes = [...document.querySelectorAll('${kind === 'video' ? 'video' : 'img'}')].map(el => ({
      src: el.currentSrc || el.src || '',
      w: ${kind === 'video' ? 'el.videoWidth' : 'el.naturalWidth'} || 0,
      h: ${kind === 'video' ? 'el.videoHeight' : 'el.naturalHeight'} || 0,
    })).filter(x => x.src && x.w > 120);
    nodes.sort((a, b) => (b.w * b.h) - (a.w * a.h));
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    return nodes[0] || null;
  })()`);
  if (!best?.src) throw new Error('Muse 找不到生成的媒体元素');
  return tools.blobFromTab(tabId, best.src, kind === 'video' ? 'video/mp4' : 'image/webp');
});
